@RestController
@RequestMapping("/api/files")
public class FileTransferController {

    private final Path storageDirectory = Paths.get("/var/app/uploads");

    @PostMapping(value = "/upload", consumes = MediaType.MULTIPART_FORM_DATA_VALUE)
    public Mono<ResponseEntity<String>> uploadFile(@RequestPart("file") FilePart filePart) {
        Path destination = storageDirectory.resolve(filePart.filename());

        return filePart.transferTo(destination)
                .then(Mono.just(ResponseEntity.ok("File uploaded successfully: " + filePart.filename())));
    }

    @GetMapping("/download/{fileName}")
    public Mono<ResponseEntity<Resource>> downloadFile(@PathVariable String fileName) {
        Path file = storageDirectory.resolve(fileName);
        Resource resource = new FileSystemResource(file);

        return Mono.fromCallable(() -> {
            if (!resource.exists() || !resource.isReadable()) {
                throw new ResponseStatusException(HttpStatus.NOT_FOUND, "File not found");
            }
            return ResponseEntity.ok()
                    .header(HttpHeaders.CONTENT_DISPOSITION, "attachment; filename=\"" + resource.getFilename() + "\"")
                    .contentType(MediaType.APPLICATION_OCTET_STREAM)
                    .body(resource);
        }).subscribeOn(Schedulers.boundedElastic());
    }
}
